import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { HttpClient } from '@angular/common/http';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css'],
})
export class AppComponent implements OnInit {
  title = 'Innovacion CRM';
  apiStatus = 'Conectando...';

  constructor(private http: HttpClient) {}

  ngOnInit() {
    this.checkApiHealth();
  }

  checkApiHealth() {
    this.http.get<any>('http://backend:3000/api/health')
      .subscribe({
        next: (response) => {
          this.apiStatus = `✓ API Conectada (${response.timestamp})`;
        },
        error: () => {
          this.apiStatus = '✗ Error al conectar API';
        }
      });
  }
}
<div style="padding: 20px; font-family: Arial, sans-serif;">
  <h1>{{ title }}</h1>
  <p style="color: #666;">Sistema CRM para Innovacion S.A.</p>

  <div style="background: #f0f0f0; padding: 15px; border-radius: 4px; margin-top: 20px;">
    <h3>Estado del Sistema</h3>
    <p>{{ apiStatus }}</p>
  </div>

  <div style="margin-top: 20px;">
    <h3>Módulos</h3>
    <ul>
      <li>Gestión de Clientes</li>
      <li>Gestión de Contactos</li>
      <li>Seguimiento de Oportunidades</li>
      <li>Gestión de Actividades</li>
      <li>Reportes</li>
    </ul>
  </div>
</div>
